package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"log"
	"os"
)

// NodeState tracks the broadcast values seen by this node
type NodeState struct {
	BroadcastMap map[int]int // msg_id -> value
}

func NewNodeState() *NodeState {
	return &NodeState{
		BroadcastMap: make(map[int]int),
	}
}

// BroadcastMsg represents a broadcast request
type BroadcastMsg struct {
	MsgID   int     `json:"msg_id"`
	Message int     `json:"message"`
}

// BroadcastOk represents acknowledgment of a broadcast
type BroadcastOk struct {
	InReplyTo int `json:"in_reply_to"`
}

// ReadMsg represents a read request
type ReadMsg struct {
	MsgID int `json:"msg_id"`
}

// ReadOk represents the response to a read request
type ReadOk struct {
	InReplyTo  int    `json:"in_reply_to"`
	Messages   []int  `json:"messages"`
}

// TopologyMsg represents a topology request
type TopologyMsg struct {
	MsgID     int       `json:"msg_id"`
	Topology  map[string][]string `json:"topology"`
}

// TopologyOk represents acknowledgment of a topology request
type TopologyOk struct {
	InReplyTo int `json:"in_reply_to"`
}

// MaelstromNode is the main node handler
type MaelstromNode struct {
	state *NodeState
	nodeID string
}

func NewMaelstromNode(id string) *MaelstromNode {
	return &MaelstromNode{
		state: NewNodeState(),
		nodeID: id,
	}
}

func (n *MaelstromNode) Init(id string, nodeIDs []string) {
	n.nodeID = id
	log.Printf("Initializing node %s", id)
}

func (n *MaelstromNode) Broadcast(msg BroadcastMsg) Reply[BroadcastOk] {
	n.state.BroadcastMap[msg.MsgID] = msg.Message
	return Reply(BroadcastOk{InReplyTo: msg.MsgID})
}

func (n *MaelstromNode) BroadcastOK(msg BroadcastOk) {
	log.Printf("Received broadcast acknowledgment for msg_id %d", msg.InReplyTo)
}

func (n *MaelstromNode) Read(msg ReadMsg) Reply[ReadOk] {
	// Return all values that have been broadcast and acknowledged
	result := []int(nil)
	for _, v := range n.state.BroadcastMap {
		result = append(result, v)
	}
	return Reply(ReadOk{
		InReplyTo:  msg.MsgID,
		Messages:   result,
	})
}

func (n *MaelstromNode) ReadOK(msg ReadOk) {
	log.Printf("Received read response for msg_id %d", msg.InReplyTo)
}

func (n *MaelstromNode) Topology(msg TopologyMsg) Reply[TopologyOk] {
	// Acknowledge topology request even if we don't use the data
	return Reply(TopologyOk{InReplyTo: msg.MsgID})
}

func (n *MaelstromNode) TopologyOK(msg TopologyOk) {
	log.Printf("Received topology acknowledgment for msg_id %d", msg.InReplyTo)
}

func main() {
	node := NewMaelstromNode("self")
	os.Exit(maelstrom.NewNode(node).Run())
}

