		return node.Send(goprotobuf.StringType("read_ok"), respBytes)
	})

	// Handle topology requests
	_ = node.Handle("topology", func(msg goprotobuf.ProtoMessage) error {
		body, ok := msg.Body.(*goprotobuf.TopologyMsg)
		if !ok {
			return nil
		}

		// Acknowledge topology request even if we don't use the data
		resp := &TopologyOk{InReplyTo: body.MsgId}
		respBytes, _ := json.Marshal(resp)
		return node.Send(goprotobuf.StringType("topology_ok"), respBytes)
	})

	return node.Run()
