			return nil // Ignore errors
		}
		log.Printf("Received topology for msg_id %d: %v", body.MsgID, body.Topology)
		return nil // Acknowledgment sent automatically by Handle/Reply
	})

	// Run the node and wait for termination signal
	return node.Run()
}

